+/** Picks a supported language from an Accept-Language header, or `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const raw = Array.isArray(header) ? header.join(",") : header;
+  if (typeof raw !== "string" || !raw.trim()) return fallback;
+  const prefs = [];
+  for (const part of raw.split(",")) {
+    const [tagPart, ...params] = part.split(";").map((s) => s.trim());
+    if (!tagPart) continue;
+    const primary = tagPart.split("-")[0].toLowerCase();
+    let q = 1;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.+)$/i.exec(p);
+      if (m) q = Number(m[1]);
+    }
+    if (Number.isNaN(q) || q <= 0 || q > 1) continue;
+    if (LANGUAGES.includes(primary)) prefs.push({ lang: primary, q });
+  }
+  prefs.sort((a, b) => b.q - a.q);
+  return prefs[0]?.lang ?? fallback;
+}
